class ReviewsService {
    private cachedReviews: Review[] | null = null;
    private fetchPromise: Promise<Review[]> | null = null;

    private getEmbeddingServiceUrl(): string {
        const envUrl = import.meta.env.VITE_EMBEDDING_SERVICE_URL;
        const storedUrl = typeof window !== 'undefined' ? localStorage.getItem('embeddingServiceUrl') : null;
        return storedUrl || envUrl || 'http://localhost:8001';
    }

    private async runEmbeddingSearch(baseData: Review[], params: FetchReviewsParams): Promise<Review[]> {
        const query = params.search?.trim();
        if (!query) {
            return baseData;
        }

        const topK = Math.max((params.limit || 15) * 3, 15);
        const response = await fetch(`${this.getEmbeddingServiceUrl()}/search`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                query,
                hotel_id: 1,
                top_k: topK
            })
        });

        if (!response.ok) {
            throw new Error(`Embedding search failed with status ${response.status}`);
        }

        const payload = await response.json() as EmbeddingSearchResponse;
        const embeddingMatches = Array.isArray(payload.reviews) ? payload.reviews : [];

        if (embeddingMatches.length === 0) {
            return [];
        }

        const byId = new Map(baseData.map((review) => [String(review.id), review]));
        const byText = new Map(baseData.map((review) => [review.reviewText.trim().toLowerCase(), review]));
        const orderedMatches: Review[] = [];
        const seen = new Set<string>();

        for (const match of embeddingMatches) {
            const byIdMatch = byId.get(String(match.id));
            const byTextMatch = byText.get((match.text || '').trim().toLowerCase());
            const resolved = byIdMatch || byTextMatch;
            if (!resolved) {
                continue;
            }

            const key = String(resolved.id);
            if (!seen.has(key)) {
                orderedMatches.push(resolved);
                seen.add(key);
            }
        }

        return orderedMatches;
    }

    private async getBaseData(): Promise<Review[]> {
        if (this.cachedReviews) return this.cachedReviews;
        if (this.fetchPromise) return this.fetchPromise;

        this.fetchPromise = (async () => {
            try {
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 5000);

                const response = await fetch('http://127.0.0.1:8000/reviews', {
                    signal: controller.signal
                });

                clearTimeout(timeoutId);

                if (!response.ok) {
                    throw new Error(`API HTTP error! Status: ${response.status}`);
                }

                const data = await response.json();

                if (Array.isArray(data) && data.length > 0) {
                    const mappedData: Review[] = data.map((item: any) => ({
                        id: item.id || Math.random().toString(),
                        rating: typeof item.rating === 'number' ? item.rating : 5,
                        userName: item.userName || item.reviewerName || 'Anonymous',
                        reviewText: item.reviewText || '',
                        sentiment: item.sentiment || 'Neutral',
                        categories: Array.isArray(item.categories) ? item.categories : [],
                        source: item.source || item.platform || 'Unknown',
                        date: item.date || new Date().toISOString().split('T')[0],
                        status: item.status || 'Pending',
                        language: item.language || 'English',
                        photos: Array.isArray(item.photos) ? item.photos : [],
                        keyPhrases: Array.isArray(item.keyPhrases) ? item.keyPhrases : [],
                        summary: item.summary || '',
                        platformReviewId: item.platformReviewId || '',
                        replyStatus: item.replyStatus || 'Unreplied',
                        hasReply: item.hasReply || 'No',
                        isAiReply: item.isAiReply || false
                    }));

                    this.cachedReviews = mappedData;
                    return mappedData;
                }

                throw new Error('API returned an empty or invalid array format.');
            } catch (error) {
                console.warn('Real API fetch failed, falling back to local MOCK_REVIEWS:', error);
                this.cachedReviews = [...MOCK_REVIEWS];
                return this.cachedReviews;
            } finally {
                this.fetchPromise = null;
            }
        })();

        return this.fetchPromise;
    }

    /**
     * Simulated Endpoint: GET /api/reviews
     * Handles server-side pagination, sorting, and filtering.
     */
    async getReviews(params: FetchReviewsParams): Promise<PaginatedResponse<Review>> {
        // Simulate network call overhead from the mock layer architecture
        try {
            await apiClient.get('/api/reviews', params as Record<string, unknown>);
        } catch(e) { /* ignore to allow mock fallback */ }

        const baseData = await this.getBaseData();
        let filteredData = [...baseData];

        // Apply search mode based on UI toggle
        if (params.search) {
            if (params.useEmbeddingSearch) {
                try {
                    filteredData = await this.runEmbeddingSearch(filteredData, params);
                } catch (error) {
                    console.warn('Embedding search failed, falling back to text search:', error);
                    const query = params.search.toLowerCase();
                    filteredData = filteredData.filter(
                        (r) => r.reviewText.toLowerCase().includes(query) || r.userName.toLowerCase().includes(query)
                    );
                }
            } else {
                const query = params.search.toLowerCase();
                filteredData = filteredData.filter(
                    (r) => r.reviewText.toLowerCase().includes(query) || r.userName.toLowerCase().includes(query)
                );
            }
        }

        if (params.rating && params.rating.length > 0) {
            filteredData = filteredData.filter(r => params.rating!.includes(r.rating));
        }
        if (params.sentiment && params.sentiment.length > 0) {
            filteredData = filteredData.filter(r => params.sentiment!.includes(r.sentiment));
        }
        if (params.source && params.source.length > 0) {
            filteredData = filteredData.filter(r => params.source!.includes(r.source));
        }
        if (params.category && params.category.length > 0) {
            filteredData = filteredData.filter(r => r.categories.some(cat => params.category!.includes(cat)));
        }
        if (params.language && params.language.length > 0) {
            filteredData = filteredData.filter(r => params.language!.includes(r.language || 'English'));
        }
        if (params.status && params.status.length > 0) {
            filteredData = filteredData.filter(r => params.status!.includes(r.status));
        }
        if (params.hasAiReply) {
            filteredData = filteredData.filter(r => r.status !== 'Pending');
        }

        // Apply date range filter
        if (params.dateFrom || params.dateTo) {
            filteredData = filteredData.filter(r => {
                const reviewDate = new Date(r.date).getTime();
                const fromDate = params.dateFrom ? new Date(params.dateFrom).getTime() : -Infinity;
                const toDate = params.dateTo ? new Date(params.dateTo).getTime() : Infinity;
                return reviewDate >= fromDate && reviewDate <= toDate;
            });
        }

        // Apply Sorting
        const sortBy = params.sortBy || 'date';
        const sortOrder = params.sortOrder || 'desc';
        filteredData.sort((a, b) => {
            if (sortBy === 'date') {
                return sortOrder === 'asc'
                    ? new Date(a.date).getTime() - new Date(b.date).getTime()
                    : new Date(b.date).getTime() - new Date(a.date).getTime();
            }
            if (sortBy === 'rating') {
                return sortOrder === 'asc' ? a.rating - b.rating : b.rating - a.rating;
            }
            return 0;
        });

        const total = filteredData.length;
        const page = params.page || 0;
        const limit = params.limit || 15;
        const totalPages = Math.max(1, Math.ceil(total / limit));

        const paginatedData = filteredData.slice(page * limit, (page + 1) * limit);

        return {
            data: paginatedData,
            total,
            page,
            limit,
            totalPages
        };
    }

    /**
     * Simulated Endpoint: GET /api/reviews/stats
     */
    async getStats(): Promise<ReviewStats> {
        try {
            await apiClient.get('/api/reviews/stats');
        } catch(e) { /* ignore */ }

        const reviews = await this.getBaseData();
        const totalReviews = reviews.length;
        let totalRating = 0;
        let pendingReplies = 0;
        let sentimentScore = 0;

        reviews.forEach(review => {
            totalRating += review.rating;
            if (review.status === 'Pending' || review.status === 'AI Draft') {
                pendingReplies++;
            }
            if (review.sentiment === 'Positive') sentimentScore += 1;
            else if (review.sentiment === 'Negative') sentimentScore -= 1;
        });

        const averageRating = totalReviews > 0 ? Number((totalRating / totalReviews).toFixed(1)) : 0;
        const normalizedSentiment = totalReviews > 0
            ? Math.round(((sentimentScore / totalReviews) + 1) * 50)
            : 50;

        return {
            totalReviews,
            averageRating,
            pendingReplies,
            sentimentScore: normalizedSentiment
        };
    }

    async getOptions(): Promise<{ sources: string[], categories: string[] }> {
        const reviews = await this.getBaseData();
        return {
            sources: Array.from(new Set(reviews.map(r => r.source))).sort(),
            categories: Array.from(new Set(reviews.flatMap(r => r.categories || []))).sort()
        };
    }

    /**
     * Endpoint: POST /api/reviews/generate
     */
    async generateReply(review: Review, tone: 'professional' | 'casual' | 'standard' = 'standard', length: 'short' | 'standard' = 'standard'): Promise<string> {
        try {
            const result = await apiClient.post<{ reply: string }>('/api/reviews/generate', {
                reviewId: review.id,
                tone,
                length,
                reviewText: review.reviewText,
                userName: review.userName,
                sentiment: review.sentiment,
                source: review.source,
            });

            if (result?.reply && typeof result.reply === 'string') {
                return result.reply;
            }
        } catch (e) {
            console.warn('Backend reply generation failed, falling back to local template.', e);
        }

        let fallback = `Dear ${review.userName}, \n\nThank you so much for your feedback! `;

        if (review.sentiment === 'Positive') {
            fallback += "We're thrilled to hear that you had a wonderful experience. ";
        } else if (review.sentiment === 'Negative') {
            fallback += "We sincerely apologize that your experience did not meet expectations. We take this seriously and will improve. ";
        } else {
            fallback += "We appreciate your balanced feedback and will use it to enhance our services. ";
        }

        if (tone === 'professional') {
            fallback = `Dear ${review.userName}, \n\nWe acknowledge your review and appreciate the time you took to provide feedback. Our team is committed to excellence. `;
        }

        if (length === 'short') {
            fallback = `Hi ${review.userName}, thanks for the review! We appreciate your insights.`;
        } else {
            fallback += `\n\nWe hope to welcome you back soon!`;
        }

        return fallback;
    }

    /**
     * Simulated Endpoint: PUT /api/reviews/:id/status
     */
    async updateReviewStatus(reviewId: string | number, status: Review['status']): Promise<void> {
        try {
            await apiClient.put(`/api/reviews/${reviewId}/status`, { status });
        } catch(e) { /* ignore */ }
        const reviews = await this.getBaseData();
        const review = reviews.find(r => r.id === reviewId);
        if (review) review.status = status;
    }

    /**
     * Simulated Endpoint: POST /api/reviews/:id/reply
     */
    async saveReply(reviewId: string | number, replyText: string): Promise<void> {
        try {
            await apiClient.post(`/api/reviews/${reviewId}/reply`, { replyText });
        } catch(e) { /* ignore */ }
        const reviews = await this.getBaseData();
        const review = reviews.find(r => r.id === reviewId);
        if (review) {
            review.status = 'Replied';
        }
    }

    /**
     * Clear the cached reviews data to force a fresh fetch from the backend.
     */
    clearCache(): void {
        this.cachedReviews = null;
        this.fetchPromise = null;
    }
}

export const reviewsService = new ReviewsService();
